                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<UInt8>.HalfVector in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<UInt8>.HalfVector.self, capacity: 1) {
                    result in
                    unsafe highwayHalfVectorResizingU8ToU8InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.HalfVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
